html:
{% set bill = frappe.utils.parse_json(doc.bill_details) if doc.bill_details else None %}
<div dir="{{ 'rtl' if frappe.lang in ['ar', 'fa', 'he', 'ur'] else 'ltr' }}">
<div class="c big">{{ frappe.db.get_value("Company", doc.company, "company_name") }}</div>
<div class="c">{{ _("Bill") }} — {{ _("not a tax invoice") }}</div>
<hr>
<table>
<tr><td>{% if doc.resto_table %}{{ _("Table {0}", context="Resto").format(doc.resto_table) }}{% else %}{{ _(doc.order_type, context="Resto") }}{% endif %}</td><td class="r">{{ doc.name }}</td></tr>
<tr><td>{{ _("Waiter") }}: {{ (frappe.db.get_value("User", doc.waiter, "full_name") or doc.waiter) if doc.waiter else "" }}</td><td class="r">{{ frappe.utils.format_datetime(doc.bill_requested_at or frappe.utils.now_datetime(), "dd-MM HH:mm") }}</td></tr>
{% if doc.order_type == "Dine In" %}<tr><td>{{ _("Guests") }}: {{ doc.guests }}</td><td></td></tr>{% endif %}
{% if doc.customer_name %}<tr><td colspan="2">{{ doc.customer_name }} {{ doc.phone or "" }}</td></tr>{% endif %}
</table>
<hr>
{% if bill %}
<table>
{% for d in bill["items"] %}<tr><td>{{ d["description"] }}<br><small>{{ d["qty"]|int if d["qty"] == d["qty"]|int else d["qty"] }} × {{ frappe.format(d["rate"], {"fieldtype": "Currency"}) }}</small></td><td class="r">{{ frappe.format(d["amount"], {"fieldtype": "Currency"}) }}</td></tr>{% endfor %}
</table>
<hr>
<table>
<tr><td>{{ _("Items Total") }}</td><td class="r">{{ frappe.format(bill["total"], {"fieldtype": "Currency"}) }}</td></tr>
{% if bill["discount"] %}<tr><td>{{ _("Discount") }}</td><td class="r">-{{ frappe.format(bill["discount"], {"fieldtype": "Currency"}) }}</td></tr>{% endif %}
{% for t in bill["taxes"] %}<tr><td>{{ t["description"] }}</td><td class="r">{{ frappe.format(t["amount"], {"fieldtype": "Currency"}) }}</td></tr>{% endfor %}
{% if bill["rounding_adjustment"] %}<tr><td>{{ _("Rounding") }}</td><td class="r">{{ frappe.format(bill["rounding_adjustment"], {"fieldtype": "Currency"}) }}</td></tr>{% endif %}
<tr class="big"><td>{{ _("To Pay") }}</td><td class="r">{{ frappe.format(bill["payable"], {"fieldtype": "Currency"}) }}</td></tr>
{% if bill["guests"] > 1 %}<tr><td>{{ _("Per Guest") }} ({{ bill["guests"] }})</td><td class="r">{{ frappe.format(bill["per_guest"], {"fieldtype": "Currency"}) }}</td></tr>{% endif %}
</table>
{% else %}<p>{{ _("Press Print Bill on the floor screen to prepare the bill.") }}</p>{% endif %}
<hr><div class="c">{{ _("Thank you", context="Resto") }}</div>
</div>
